        Scanner sc = new Scanner(System.in);
        String title = sc.next();

        // Bug: Incorrect instantiation of non-static inner class
        PrinterConfig.PrintEngine engine = new PrinterConfig.PrintEngine();
        engine.print(title);
    }
}

